      "explanation": "口服给药经过胃肠道吸收，虽然起效较慢，但方便、经济，严重过敏和感染风险相对较低，是日常治疗中最安全、最常用的给药方法。注射和吸入可能造成更快更强烈的不良反应，纳肛也有局部刺激和吸收差异。"
